script.text:

function load$GridAllocationDetail$(g) {
	g._focusWhenTabChanged();

	g.add_commandEvent(on$GridAllocationDetail$ExecuteCommand);
	g.add_itemValueChanged(onChange$GridAllocationDetail);
	g.add_onRender(on$GridAllocationDetail$GridRender);
	g.$a = {
		s5: '[s5]:=[$hs9tien] * [s4] / 100'
		, t_s4: ['t_s4', 's4']
		, t_s5: ['t_s5', 's5']
	};
}
function dispose$GridAllocationDetail$(g) {
	try {g.remove_commandEvent(on$GridAllocationDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridAllocationDetail);} catch (ex) {}
	try {g.remove_onRender(on$GridAllocationDetail$GridRender);} catch (ex) {}
}
function on$GridAllocationDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm, id = g.get_id(), s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
	switch (action) {
		case 'Check':
			if ($func.trim(f.getItemValue('loai_hs')) == '9') {
				if !g.validRowExpression('s4', '[$t_s4] == 100') break;
				if !g.validRowExpression('s5', '[$t_s5] == [$hs9tien]') break;
			}
			break;
		default:
			break;
	}
}
function onChange$GridAllocationDetail(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 's4':
			g.validExpression(o, [g.$a.s5], [g.$a.t_s4, g.$a.t_s5], []);
			break;
		case 's5':
			g.validExpression(o, [], [g.$a.t_s5], []);
			break;
		default:
			break;
	}
}
function on$GridAllocationDetail$GridRender(sender, eventArgs) {
	var g = eventArgs.grid;
	var f = g.get_element().parentForm, v = $func.trim(f.getItemValue('loai_hs'));
	g._suspendLayout();
	g._setColumnVisible(g._getColumnOrder('s6'), (v != 9));
	g._setColumnVisible(g._getColumnOrder('s4'), (v == 9));
	g._setColumnVisible(g._getColumnOrder('s5'), (v == 9));
	g._resumeLayout();
}
